export interface LineDraft { code: string; description: string; unitCents: number; units: number; rebateCentsPerUnit: number; }
export interface InvoiceTotals { subtotalCents: number; taxCents: number; totalCents: number; }

function validate(draft: LineDraft): LineDraft {
  const description = draft.description.trim();
  if (!draft.code.trim() || !description) throw new Error('Missing text');
  if (![draft.unitCents, draft.units, draft.rebateCentsPerUnit].every(Number.isSafeInteger)) throw new Error('Invalid number');
  if (draft.unitCents < 0 || draft.units <= 0 || draft.rebateCentsPerUnit < 0 || draft.rebateCentsPerUnit > draft.unitCents) throw new Error('Invalid amount');
  return { ...draft, description };
}

export class InvoiceBook {
  private readonly lines = new Map<string, LineDraft>();
  private pending?: LineDraft;
  private query = '';
  begin(draft: LineDraft): void {
    if (this.pending) throw new Error('Draft already pending');
    const copy = validate(draft);
    if (this.lines.has(copy.code)) throw new Error('Duplicate code');
    this.pending = copy;
  }
  save(): LineDraft {
    if (!this.pending) throw new Error('No pending draft');
    const saved = { ...this.pending };
    if (this.lines.has(saved.code)) throw new Error('Duplicate code');
    this.lines.set(saved.code, saved);
    this.pending = undefined;
    return { ...saved };
  }
  cancel(): void {
    if (!this.pending) throw new Error('No pending draft');
    this.pending = undefined;
  }
  delete(code: string): boolean { return this.lines.delete(code); }
  search(query: string): LineDraft[] {
    this.query = query.toLowerCase();
    return this.visible();
  }
  resetSearch(): LineDraft[] {
    this.query = '';
    return this.visible();
  }
  visible(): LineDraft[] {
    return Array.from(this.lines.values())
      .filter(line => line.description.toLowerCase().includes(this.query))
      .map(line => ({ ...line }));
  }
  totals(): InvoiceTotals {
    const subtotalCents = Array.from(this.lines.values()).reduce(
      (sum, line) => sum + (line.unitCents - line.rebateCentsPerUnit) * line.units,
      0
    );
    const taxCents = Math.floor(subtotalCents * 0.08);
    return { subtotalCents, taxCents, totalCents: subtotalCents + taxCents };
  }
}

