import { InvoiceBook, LineDraft } from './solution';

function assert(value: boolean, message: string): void { if (!value) throw new Error(message); }
function equal(actual: unknown, expected: unknown, message: string): void { if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`); }
function deepEqual(actual: unknown, expected: unknown, message: string): void { if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(`${message}: ${JSON.stringify(actual)}`); }
function throws(action: () => unknown, message: string): void { let didThrow = false; try { action(); } catch { didThrow = true; } if (!didThrow) throw new Error(message); }

const book = new InvoiceBook();
deepEqual(book.visible(), [], 'empty book');
deepEqual(book.totals(), { subtotalCents: 0, taxCents: 0, totalCents: 0 }, 'empty totals');
throws(() => book.save(), 'save without draft throws');
throws(() => book.cancel(), 'cancel without draft throws');
assert(!book.delete('missing'), 'unknown delete returns false');

const first: LineDraft = { code: 'A', description: '  Alpha Service  ', unitCents: 101, units: 3, rebateCentsPerUnit: 1 };
book.begin(first);
first.description = 'mutated';
first.unitCents = 999;
throws(() => book.begin({ code: 'X', description: 'x', unitCents: 1, units: 1, rebateCentsPerUnit: 0 }), 'only one draft may be pending');
book.save();
const second: LineDraft = { code: 'B', description: 'Beta ITEM', unitCents: 250, units: 2, rebateCentsPerUnit: 50 };
book.begin(second);
book.save();
deepEqual(book.visible().map(line => line.code), ['A', 'B'], 'creation order retained');
equal(book.visible()[0].description, 'Alpha Service', 'description trimmed and input copied');
deepEqual(book.totals(), { subtotalCents: 700, taxCents: 56, totalCents: 756 }, 'totals include rebates and tax');

book.begin({ code: 'C', description: 'cancel me', unitCents: 10, units: 1, rebateCentsPerUnit: 0 });
book.cancel();
deepEqual(book.visible().map(line => line.code), ['A', 'B'], 'cancel discards pending draft');

book.search('ALPHA');
deepEqual(book.visible().map(line => line.code), ['A'], 'search is case insensitive');
book.search('item');
deepEqual(book.visible().map(line => line.code), ['B'], 'search uses description substring');
book.search('');
deepEqual(book.visible().map(line => line.code), ['A', 'B'], 'empty search matches all');
book.search('no match');
deepEqual(book.visible(), [], 'unmatched search is empty');
book.resetSearch();
deepEqual(book.visible().map(line => line.code), ['A', 'B'], 'reset restores all lines');

const exposed = book.visible();
exposed[0].description = 'corrupt';
exposed.pop();
equal(book.visible()[0].description, 'Alpha Service', 'returned lines are copied');
equal(book.visible().length, 2, 'returned array is copied');
const totals = book.totals();
totals.subtotalCents = -1;
equal(book.totals().subtotalCents, 700, 'returned totals are copied');

throws(() => book.begin({ code: '', description: 'x', unitCents: 1, units: 1, rebateCentsPerUnit: 0 }), 'empty code rejected');
throws(() => book.begin({ code: 'X', description: '   ', unitCents: 1, units: 1, rebateCentsPerUnit: 0 }), 'blank description rejected');
throws(() => book.begin({ code: 'X', description: 'x', unitCents: -1, units: 1, rebateCentsPerUnit: 0 }), 'negative unit price rejected');
throws(() => book.begin({ code: 'X', description: 'x', unitCents: 1.5, units: 1, rebateCentsPerUnit: 0 }), 'unsafe unit price rejected');
throws(() => book.begin({ code: 'X', description: 'x', unitCents: 1, units: 0, rebateCentsPerUnit: 0 }), 'zero units rejected');
throws(() => book.begin({ code: 'X', description: 'x', unitCents: 1, units: Number.MAX_SAFE_INTEGER + 1, rebateCentsPerUnit: 0 }), 'unsafe units rejected');
throws(() => book.begin({ code: 'X', description: 'x', unitCents: 10, units: 1, rebateCentsPerUnit: -1 }), 'negative rebate rejected');
throws(() => book.begin({ code: 'X', description: 'x', unitCents: 10, units: 1, rebateCentsPerUnit: 11 }), 'rebate above price rejected');
throws(() => book.begin({ code: 'A', description: 'duplicate', unitCents: 1, units: 1, rebateCentsPerUnit: 0 }), 'duplicate saved code rejected');

assert(book.delete('A'), 'known code deleted');
deepEqual(book.visible().map(line => line.code), ['B'], 'delete updates visible lines');
deepEqual(book.totals(), { subtotalCents: 400, taxCents: 32, totalCents: 432 }, 'delete updates totals');

const rounding = new InvoiceBook();
rounding.begin({ code: 'R', description: 'round', unitCents: 6, units: 1, rebateCentsPerUnit: 0 });
rounding.save();
deepEqual(rounding.totals(), { subtotalCents: 6, taxCents: 0, totalCents: 6 }, 'tax uses Math.round below half cent');
rounding.begin({ code: 'S', description: 'round up', unitCents: 1, units: 1, rebateCentsPerUnit: 0 });
rounding.save();
deepEqual(rounding.totals(), { subtotalCents: 7, taxCents: 1, totalCents: 8 }, 'tax uses Math.round above half cent');

